<?php
require dirname(__DIR__,2).'/app/bootstrap.php'; require_login();
$id=(int)($_GET['id']??0); $st=db()->prepare('SELECT c.*,cat.name category,u.name creator FROM credentials c LEFT JOIN categories cat ON cat.id=c.category_id LEFT JOIN users u ON u.id=c.created_by WHERE c.id=?');$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('Data tidak ditemukan.');}
$secret='';$show=false;
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='reveal' && in_array(current_user()['role'],['admin','it'],true)){verify_csrf();$secret=decrypt_secret($r['password_ciphertext']);$show=true;audit('reveal_secret','credential',$id,'Password kredensial dibuka');}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='delete'){require_role(['admin']);verify_csrf();db()->prepare('DELETE FROM credentials WHERE id=?')->execute([$id]);audit('delete','credential',$id,'Kredensial dihapus');flash('Kredensial dihapus.');redirect('credentials/index.php');}
layout_header('Detail kredensial');
?>
<div class="welcome-row"><div><p class="eyebrow">VAULT / DETAIL</p><h1><?=e($r['title'])?></h1><p class="muted">Detail akses layanan dan pengaturan kredensial.</p></div><div class="button-row"><a class="btn btn-ghost" href="<?=e(cfg('app_url'))?>/credentials/index.php">← Kembali</a><?php if(can_edit()): ?><a class="btn btn-primary" href="<?=e(cfg('app_url'))?>/credentials/edit.php?id=<?=$id?>">Edit data</a><?php endif; ?></div></div>
<div class="detail-grid"><section class="panel"><div class="panel-heading"><div><h2>Informasi layanan</h2><p>Data identitas login</p></div><span class="tag"><?=e($r['service_type'])?></span></div><dl class="detail-list"><div><dt>Nama layanan</dt><dd><?=e($r['title'])?></dd></div><div><dt>URL web / APK</dt><dd><?php if($r['url']): ?><a class="text-link" href="<?=e($r['url'])?>" target="_blank" rel="noopener noreferrer"><?=e($r['url'])?> ↗</a><?php else: ?>—<?php endif; ?></dd></div><div><dt>Username</dt><dd><?=e($r['username']?:'—')?></dd></div><div><dt>Email</dt><dd><?=e($r['email']?:'—')?></dd></div><div><dt>Kategori</dt><dd><?=e($r['category']??'Tanpa kategori')?></dd></div><div><dt>Catatan</dt><dd class="notes"><?=nl2br(e($r['notes']?:'—'))?></dd></div><div><dt>Dibuat oleh</dt><dd><?=e($r['creator']??'—')?></dd></div></dl></section><aside class="panel"><div class="panel-heading"><div><h2>Secret vault</h2><p>Password tersimpan terenkripsi</p></div><span class="secure-pill">◈ AES-GCM</span></div><?php if(in_array(current_user()['role'],['admin','it'],true)): ?><form method="post" class="form-stack"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reveal"><button class="btn btn-secondary btn-block">◉ Tampilkan password</button></form><?php if($show): ?><div class="secret-box"><code id="secret-value"><?=e($secret?:'(kosong atau gagal didekripsi)')?></code><button class="btn btn-ghost btn-small" type="button" data-copy="#secret-value">Salin</button></div><p class="field-help">Jangan tinggalkan password terlihat di layar bersama.</p><?php endif; ?><?php else: ?><p class="muted">Role viewer tidak memiliki izin membuka password rahasia.</p><?php endif; ?><?php if(current_user()['role']==='admin'): ?><hr><form method="post" onsubmit="return confirm('Hapus kredensial ini secara permanen?')" class="form-stack"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-block">Hapus kredensial</button></form><?php endif; ?></aside></div>
<?php layout_footer(); ?>
